void dfs(vector<vector<int>>& adj, int u,
         vector<bool>& visited, vector<int>& order) {
    visited[u] = true;
    for (int v : adj[u])
        if (!visited[v]) dfs(adj, v, visited, order);
    order.push_back(u);            // post-order / finish time
}

def dfs(adj, u, visited, order):
    visited.add(u)
    for v in adj[u]:
        if v not in visited:
            dfs(adj, v, visited, order)
    order.append(u)        # post-order / finish time
